class Command(BaseCommand):
    help = "بانک الزامات قانونی و سازمانی سایپا یدک را با نسخه‌ی نهایی و بدون تکراری (۱۱۱ ردیف) پاک و جایگزین می‌کند."

    def handle(self, *args, **options):
        LegalRequirement.objects.all().delete()
        for row in ROWS:
            LegalRequirement.objects.create(**row)
        self.stdout.write(self.style.SUCCESS(f"ثبت شد: {len(ROWS)} الزام قانونی/سازمانی (بدون تکراری)."))
